import{_ as s,c as e,o as n,a0 as t}from"./chunks/framework.C1J0Vcxi.js";const u=JSON.parse('{"title":"第十九周：L2 Cache Lim运行环境配置","description":"","frontmatter":{"title":"第十九周：L2 Cache Lim运行环境配置","date":"2026-04-12"},"headers":[],"relativePath":"周报-Oveln/archive/2026-04-12-周报十九.md","filePath":"周报-Oveln/archive/2026-04-12-周报十九.md"}'),p={name:"周报-Oveln/archive/2026-04-12-周报十九.md"};function l(i,a,o,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="第十九周工作总结" tabindex="-1">第十九周工作总结 <a class="header-anchor" href="#第十九周工作总结" aria-label="Permalink to &quot;第十九周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本周完成了 <strong>L2 Cache Lim 运行环境的完整配置</strong></p><h2 id="核心工作-l2-cache-lim-运行环境" tabindex="-1">核心工作：L2 Cache Lim 运行环境 <a class="header-anchor" href="#核心工作-l2-cache-lim-运行环境" aria-label="Permalink to &quot;核心工作：L2 Cache Lim 运行环境&quot;">​</a></h2><h3 id="技术背景" tabindex="-1">技术背景 <a class="header-anchor" href="#技术背景" aria-label="Permalink to &quot;技术背景&quot;">​</a></h3><p>L2 Cache Lim 是 JH7110 SoC 中 L2 Cache 的一块特殊区域，可直接映射为内存使用，相比常规 DDR 具有更确定的访问延迟（对于RTOS来说很重要）和更高的带宽，非常适合运行对延迟敏感的实时任务。</p><h3 id="完整实现链路" tabindex="-1">完整实现链路 <a class="header-anchor" href="#完整实现链路" aria-label="Permalink to &quot;完整实现链路&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        启动流程                                  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  1. SPL 自搬运          │  2. Hart0 入口      │  3. 应用启动   │</span></span>
<span class="line"><span>│     (  spl )           │     (opensbi/rustsbi) │  (embassy_app) │</span></span>
<span class="line"><span>│  0x8000000 → 0x8080000  │  → Cache Lim 跳转    │  → Cache Lim   │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h4 id="_1-spl-自搬运-u-boot" tabindex="-1">① SPL 自搬运 (u-boot) <a class="header-anchor" href="#_1-spl-自搬运-u-boot" aria-label="Permalink to &quot;① SPL 自搬运 (u-boot)&quot;">​</a></h4><p>SPL 原本运行在 <code>0x800_0000</code>，为了给 embassy_preempt 预留空间，实现了自搬运机制：</p><p><strong>新增文件</strong>: <code>arch/riscv/cpu/spl_relocate.S</code> (110 行)</p><ul><li>汇编实现的 SPL 自搬运代码</li><li>将自身从 <code>0x800_0000</code> 搬运到 <code>0x808_0000</code></li><li>修改 <code>u-boot-spl.lds</code> 链接脚本适配新地址</li></ul><p><strong>Cache2 配置</strong>:</p><ul><li>添加 <code>sifive,max-enabled-ways</code> 设备树选项</li><li>限制仅使用 12 个 Cache2 ways，为 Cache Lim 预留空间</li><li>更新 <code>cache-sifive-ccache.c</code> 驱动</li></ul><h4 id="_2-sbi-层-hart0-入口" tabindex="-1">② SBI 层 Hart0 入口 <a class="header-anchor" href="#_2-sbi-层-hart0-入口" aria-label="Permalink to &quot;② SBI 层 Hart0 入口&quot;">​</a></h4><p><strong>opensbi</strong> 修改 <code>lib/sbi/sbi_init.c</code>:</p><ul><li>Hart0 启动后直接跳转到 L2 Cache Lim 区域运行</li></ul><h4 id="_3-链接脚本与内存布局" tabindex="-1">③ 链接脚本与内存布局 <a class="header-anchor" href="#_3-链接脚本与内存布局" aria-label="Permalink to &quot;③ 链接脚本与内存布局&quot;">​</a></h4><p><strong>embassy_preempt</strong> JH7110 平台适配:</p><p>新增 <code>platforms/jh7110/link.x</code> (205 行):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* 将程序代码段放置在 L2 Cache Lim 区域 */</span></span>
<span class="line"><span>. = 0x0800_0000;</span></span>
<span class="line"><span>.text : { *(.text.init) *(.text .text.*) }</span></span></code></pre></div><p>修改 <code>memory.x</code> 内存布局定义，重构 <code>panic_handler.rs</code> (132 行) 增强异常处理能力。</p><h4 id="_4-构建系统配置与-elf-split" tabindex="-1">④ 构建系统配置与 ELF Split <a class="header-anchor" href="#_4-构建系统配置与-elf-split" aria-label="Permalink to &quot;④ 构建系统配置与 ELF Split&quot;">​</a></h4><p><strong>Makefile 更新</strong>:</p><ul><li>移除 <code>rust-objcopy</code> 步骤，直接使用 ELF 文件</li></ul><p><strong>ELF Split 配置</strong> (u-boot <code>binman.dtsi</code>):</p><p>使用 U-Boot binman 的 <code>split-elf</code> 操作自动拆分 ELF 文件：</p><div class="language-dts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@embassy-SEQ {</span></span>
<span class="line"><span>    fit,operation = &quot;split-elf&quot;;     // 启用 ELF 拆分</span></span>
<span class="line"><span>    description = &quot;Embassy Preempt OS&quot;;</span></span>
<span class="line"><span>    type = &quot;standalone&quot;;</span></span>
<span class="line"><span>    os = &quot;rtos&quot;;</span></span>
<span class="line"><span>    arch = &quot;riscv&quot;;</span></span>
<span class="line"><span>    compression = &quot;none&quot;;</span></span>
<span class="line"><span>    fit,load;    // 自动从 ELF 读取加载地址</span></span>
<span class="line"><span>    fit,data;    // 自动从 ELF 读取代码段</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    embassy_preempt {</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><strong>开发环境更新</strong> (flake.nix):</p><ul><li>添加 <code>python3Packages.pyelftools</code> 依赖（binman 解析 ELF 需要）</li></ul><h2 id="外设驱动与测试体系" tabindex="-1">外设驱动与测试体系 <a class="header-anchor" href="#外设驱动与测试体系" aria-label="Permalink to &quot;外设驱动与测试体系&quot;">​</a></h2><h3 id="gpio-驱动" tabindex="-1">GPIO 驱动 <a class="header-anchor" href="#gpio-驱动" aria-label="Permalink to &quot;GPIO 驱动&quot;">​</a></h3><p><strong>embassy_preempt_app</strong> 新增完整的 GPIO 驱动 (246 行):</p><ul><li>GPIO 引脚配置与控制</li><li>支持输入/输出模式切换</li><li>LED 测试程序 (341 行) 验证驱动功能</li></ul><h3 id="amo-指令支持" tabindex="-1">AMO 指令支持 <a class="header-anchor" href="#amo-指令支持" aria-label="Permalink to &quot;AMO 指令支持&quot;">​</a></h3><p>添加 RISC-V 原子操作指令支持，为多核同步提供硬件基础。</p><h3 id="测试程序体系" tabindex="-1">测试程序体系 <a class="header-anchor" href="#测试程序体系" aria-label="Permalink to &quot;测试程序体系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>测试程序</th><th>功能</th><th>代码量</th></tr></thead><tbody><tr><td><code>cpu_freq_test.rs</code></td><td>CPU 频率测试</td><td>73 行</td></tr><tr><td><code>ctx_switch_test.rs</code></td><td>上下文切换性能测试</td><td>133 行</td></tr><tr><td><code>led_test.rs</code></td><td>LED/GPIO 功能测试</td><td>341 行</td></tr><tr><td><code>perf_test.rs</code></td><td>综合性能测试</td><td>51 行</td></tr><tr><td><code>timer_test.rs</code></td><td>定时器精度测试</td><td>82 行</td></tr></tbody></table><h3 id="内存布局规划" tabindex="-1">内存布局规划 <a class="header-anchor" href="#内存布局规划" aria-label="Permalink to &quot;内存布局规划&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache Lim</span></span>
<span class="line"><span>0x800_0000 ┌─────────────────┐</span></span>
<span class="line"><span>           │ embassy_preempt │  ← 核心代码运行区</span></span>
<span class="line"><span>           │   应用程序       │</span></span>
<span class="line"><span>           │   SPL (自搬运前)  │</span></span>
<span class="line"><span>           ├─────────────────┤  ← SPL 自搬运</span></span>
<span class="line"><span>0x808_0000 │   SPL (运行位置)  │</span></span>
<span class="line"><span>           └─────────────────┘</span></span></code></pre></div>`,40)])])}const b=s(p,[["render",l]]);export{u as __pageData,b as default};
